/**
 * Cờ Chiếu Tướng — daily puzzle bank (machine-generated + machine-verified).
 *
 * Generated by scripts/gen-puzzles.mjs (seeded rng, deterministic):
 * mined 250 random-ply games + 4000 piece shuffles +
 * 12000 trapped-general skeletons + a forced-capture mate-in-2
 * template search (0 kept), found 871 mate-in-1
 * and 0 mate-in-2 candidates, selected 30
 * (quotas: <=12 mate-in-2, <=18 mate-in-1, red/green balanced), then
 * re-verified every entry from scratch. Re-running the generator
 * reproduces this file byte-for-byte.
 */

export interface CctPuzzle {
  /** "cct-daily-001" … */
  id: string;
  /** 25-char position string (see engine.ts stateToPos). */
  pos: string;
  /** Side to move — plays the solution. */
  turn: "r" | "g";
  mateIn: 1 | 2;
  /**
   * Canonical "c,r-c,r" moves (1-based cols/rows 1-5).
   * mate-in-1: [mate]; mate-in-2: [solverM1, forcedOppReply, solverMate].
   */
  solution: string[];
  title: { vi: string; en: string };
}

