/** Deterministic daily pick: dayNumber % PUZZLES.length. */
export function puzzleForDate(d: Date): CctPuzzle {
  const n = PUZZLES.length;
  const day = Math.floor(d.getTime() / 86400000);
  return PUZZLES[((day % n) + n) % n];
}
